//            if(sTiedBiggestRegions.GetSize() == 0)
//              {
//                // then use it as the infinite region
//                pNewInfRegion = pBiggestRegion;
//              }
//
//            // obsolete: Old biggest bounding box tie resolution - now just ray trace such cases
//            //
