//            //      // This should be the same for all faceuses.
//            //      double dLength = 1.0;
//            //      if(sTiedBiggestBoxes.GetSize() > 0 )
//            //        { dLength = sTiedBiggestBoxes[0].GetSize().Length() / 100; }
//            //
