/*******************************************************************//**
PURPOSE: Get Topological edges of this brep.

NOTES: Topological Edges are Edges that can be removed withtout changing
       the shape of the Brep, e.g. an Edge that splits a surface into two faces
       that can be removed causing the two faces to merge into one without
       changing the Brep shape.
***********************************************************************/
void SmBrep::GetTopologicalEdges(SmTArray<SmEdge*> & rTopoEdges) const
{
  // init output
  rTopoEdges.ReSet();

  // get all edges
  SmTArray<SmEdge*> sEdges;
  GetEdges(sEdges);

  // locals
  SmSurface *pSurfToKeep ;
  double     dDistBetween ;

  // add wire edges to output array
  for (ULONG ii=0; ii<sEdges.GetSize(); ii++)
    {
      SmEdge *pEdge = sEdges[ii];
      if (pEdge->IsTopological(pSurfToKeep, dDistBetween))
        {
          rTopoEdges.Add(pEdge);
        }
    }

} // end SmBrep::GetTopologicalEdges

/*******************************************************************//**
PURPOSE: Get the wire edges of this brep.

NOTES:
***********************************************************************/
void SmBrep::GetWireEdges
 (SmTArray<SmEdge*> & rWireEdges,       // out: pointers to all wireEdges in Brep
  ULONG             * pOptAttributeId)  // in : only include objects containing an attribute with this id
                                        //      NULL to ignore, default:[NULL]
 const
{
  // init output
  rWireEdges.ReSet();

  // get all edges
  SmTArray<SmEdge*> sEdges;
  GetEdges(sEdges, pOptAttributeId);

  // add wire edges to output array
  for (ULONG i=0; i<sEdges.GetSize();i++)
    {
      SmEdge *pE = sEdges[i];
      if (pE->IsWire())
        {
          rWireEdges.Add(pE);
        }
    }

} // end SmBrep::GetWireEdges

