//          SmExtent2d sNewDomain = pSurfToKeep->GetNaturalUVDomain();
//
//          // for every Face using pSurfToKeep - update pFace->Domain and Tolerance
//          for(jj=0;jj<lIters;jj++)
//            {
//              // good for composite and standalone Faces
