//                               ? SM_CAST_PTR( SmFace, pSurfToKeep->GetOwner()) // Owner on last iteration
//                               : sAllFaces[jj] ;                               // composite children on all but last iterations
//
//              // Update UVDomain
//              pFace->SetUVDomain( sNewDomain) ;
//
