/*******************************************************************//**
PURPOSE: Replace NonBSpline Face and Edge geometry with BSpline Approximations

NOTES: Removes all UVTrimCurves from Faces whose surfaces get replaced.
       Returns err when any of the approximation tries fail
***********************************************************************/
SmStatus SmBrep::ApproximateWithBSplines
 (double               dApproxTol,       // in : maximum allowed distance between approx and original shapes
  double             & dMaxAchievedTol,  // out : max of all max achieved tolerances
  SmTArray<SmFace *> * pOptFaces,        // in : optional list of tgt Faces, NULL=Check all Faces, default:[NULL]
  SmTArray<SmEdge *> * pOptEdges)        // in : optional list of tgt Edges, NULL=Check all Edges, default:[NULL]
{
  // init outputs
  dMaxAchievedTol = 0.0 ;
  SmStatus sRtn = SM_SUCCESS ; 

  // locals
  ULONG ii ;
  double dThisAchievedTol ; 
  SmTArray<SmFace *> sFaces, *pFaces ;
  SmTArray<SmEdge *> sEdges, *pEdges ;

  // Face tgts
  if(pOptFaces) { pFaces = pOptFaces ; }
  else          { GetFaces(sFaces) ;
                  pFaces = &sFaces ; 
                }
  
  // Edge tgts
  if(pOptEdges) { pEdges = pOptEdges ; }
  else          { GetEdges(sEdges) ;
                  pEdges = &sEdges ; 
                }

  // options: Faces or Edges first
  // Do faces after edges so that Edge->Surface approximations have a chance to be close to Edge->Curve approximations
  // Do faces before edges so that Edge->Surface approximations have a chance to be close to original Edge->Curve shapes

  // for every tgt Face - replace nonBSpline geometry with BSpline approximations
  for(ii=0;ii<pFaces->GetSize();ii++)
    {
      SmFace * pFace = (*pFaces)[ii] ; 

      // Replace NonBSpline Face->Curve with a BSpline approximation
      SmStatus sThisRtn = pFace->ApproximateWithBSpline(dApproxTol/2.0, dThisAchievedTol) ;

      // save max Achieved tol
      if(sThisRtn == SM_SUCCESS) { if(dMaxAchievedTol < dThisAchievedTol)
                                     { dMaxAchievedTol = dThisAchievedTol ; }
                                 }
      else                       { sRtn = SM_ERR ; 
                                   SM_ASSERT_MSG( sRtn == SM_SUCCESS,
                                                  _T("SmBrep::ApproximateWithBSplines - call SmFace::ApproximateWithBSpline() failed")) ; 
                                 }

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
      // PostApprox pFace->Surface check and draw
      if(bDebugMe)
        {
          SmBrep    * pBrep    = pFace ? pFace->GetBrep() : NULL ;
          SmSurface * pSurface = pFace->GetSurface() ;

          SM_DUMP_AND_ASSERT_VALID(pFace) ;
          SM_DUMP_AND_ASSERT_VALID(pSurface) ;

          smgfx_Erase() ;
          smgfx_SetLook(1,2, 0,0,1) ; if(pBrep)    pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(1,2, 0,1,1) ; if(pSurface) pSurface->DrawUV(8,8,FALSE, NULL,TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(2,3, 0,0,0) ; if(pFace)    pFace->Draw() ; sm_GraphicsLoop() ;
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE

    } // end iter every tgt Face replacing nonBSpline Curves with BSpline Curve approximations
  
  // for every tgt Edge - replace nonBSpline geometry with BSpline approximations
  for(ii=0;ii<pEdges->GetSize();ii++)
    {
      SmEdge * pEdge = (*pEdges)[ii] ; 

#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
      // PreApprox pEdge->Curve check and draw 
      if(bDebugMe)
        {
          SmBrep   * pBrep  = pEdge ? pEdge->GetBrep() : NULL ;
          SmCurve  * pCurve = pEdge->GetCurve() ;
          SmExtent1d sIvl   = pEdge->GetInterval() ;

          SM_DUMP_AND_ASSERT_VALID(pEdge) ;
          SM_DUMP_AND_ASSERT_VALID(pCurve) ;

          smgfx_Erase() ;
          smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(3,4, 0,1,1) ; if(pCurve) pCurve->Draw(&sIvl,TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(2,3, 0,0,0) ; if(pEdge) pEdge->Draw() ; sm_GraphicsLoop() ;
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE

      // Replace NonBSpline Edge->Curve with a BSpline approximation
      //  note: ApproxTol is divided by 2 so that future ApproxEdge/ApproxFace gaps increase by only ApproxTol
      SmStatus sThisRtn = pEdge->ApproximateWithBSpline(dApproxTol/2.0, dThisAchievedTol) ;

      // save max Achieved tol
      if(sThisRtn == SM_SUCCESS) { if(dMaxAchievedTol < dThisAchievedTol)
                                     { dMaxAchievedTol = dThisAchievedTol ; }
                                 }
      else                       { sRtn = SM_ERR ; 
                                   SM_ASSERT_MSG( sRtn == SM_SUCCESS,
                                                  _T("SmBrep::ApproximateWithBSplines - call SmEdge::ApproximateWithBSpline() failed")) ; 
                                 }
#ifdef SM_DEBUG_CODE
      // PostApprox pEdge->Curve check and draw
      if(bDebugMe)
        {
          SmBrep   * pBrep  = pEdge ? pEdge->GetBrep() : NULL ;
          SmCurve  * pCurve = pEdge->GetCurve() ;
          SmExtent1d sIvl   = pEdge->GetInterval() ;

          SM_DUMP_AND_ASSERT_VALID(pEdge) ;
          SM_DUMP_AND_ASSERT_VALID(pCurve) ;

          pEdge->RemoveUVTrimCurves() ;

          smgfx_Erase() ;
          smgfx_SetLook(1,2, 0,0,1) ; if(pBrep) pBrep->Draw(TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(3,4, 0,1,1) ; if(pCurve) pCurve->Draw(&sIvl,TRUE) ; sm_GraphicsLoop() ;
          smgfx_SetLook(2,3, 0,0,0) ; if(pEdge) pEdge->Draw() ; sm_GraphicsLoop() ;
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE

    } // end iter every tgt Edge replacing nonBSpline Curves with BSpline Curve approximations
  
  // all done
  return(sRtn) ; 

} // end SmBrep::ApproximateWithBSplines

/*******************************************************************//**
PURPOSE: Validate entity counts within the Brep.

NOTES:  Return error if they don't match.
***********************************************************************/
SmStatus SmBrep::ValidateCounts
  (ULONG lFaces,          // in : expected number of Faces        
   ULONG lEdges,          // in : expected number of Edges        
   ULONG lVertices,       // in : expected number of Vertices     
   ULONG lWireEdges,      // in : expected number of WireEdges    
   ULONG lLaminaEdges,    // in : expected number of LaminaEdges  
   ULONG lManifoldEdges,  // in : expected number of ManifoldEdges
   ULONG lRegions,        // in : expected number of Regions      
   ULONG lShells)         // in : expected number of Shells       
  const
{
  // locals
  SmTArray<SmRegion*> sRegions ;
  SmTArray<SmShell*>  sShells ;
  SmTArray<SmFace*>   sFaces ;
  SmTArray<SmEdge*>   sEdges ;
  SmTArray<SmVertex*> sVertices ;

  GetRegions(sRegions) ;
  GetFaces(sFaces) ;
  GetEdges(sEdges) ;
  GetVertices(sVertices) ;

  // count locals
  ULONG lWires     = 0 ;
  ULONG lLaminas   = 0 ;
  ULONG lManifold  = 0 ;
  ULONG lNumShells = 0 ;

  // Edge type counts
  for (ULONG jj=0; jj<sEdges.GetSize(); jj++) 
    {
      SmEdge *pE = sEdges[jj] ;
      if (pE->IsWire()) lWires++ ;
      if (pE->IsLamina()) lLaminas++ ;
      if (pE->IsManifold()) lManifold++ ;
    }

  // shell counts
  for (ULONG ii=0; ii<sRegions.GetSize(); ii++) 
    {
      SmRegion *pR = sRegions[ii] ;
      pR->GetShells(sShells) ;
      lNumShells += sShells.GetSize() ;
    }

  // pretty print locals
  TCHAR sHead[SM_TBLOCK_SIZE], sBuff[SM_TBLOCK_SIZE] ;
  smos_sprintf(sHead,_T("%s"), _T("SmBrep::ValidateCounts() - Different ") ) ;

#define USE_HELPFUL_PRINT 1

 #if USE_HELPFUL_PRINT
  // Useful print of parameters for subsequent call to ValidateCounts
  // nFaces, nEdges, nVertices, nWireEdges, nLaminaEdges, nManifoldEdges, nRegions, nShells
  smos_sprintf(sBuff, _T("SmBrep::ValidateCounts() Print:         [%lu, %lu, %lu, %lu, %lu, %lu, %lu, %lu]\n"), sFaces.GetSize(), sEdges.GetSize(), sVertices.GetSize(), lWires, lLaminas, lManifold, sRegions.GetSize(), lNumShells);
  smos_WriteBuffer(sBuff);
#endif

  SmStatus eStat = SM_SUCCESS;
  // bad count pretty print messages
  if(lFaces         != sFaces.GetSize())   { smos_sprintf(sBuff,_T("SmBrep::ValidateCounts() - Different Face Count          [exp:%lu, act:%lu]\n"),lFaces        ,sFaces.GetSize()  ) ;
                                             SE_MSG(SM_ERR,sBuff) ;
                                             eStat = SM_ERR;
                                           }
  if(lEdges         != sEdges.GetSize())   { smos_sprintf(sBuff,_T("%.512sEdge Count          [exp:%lu, act:%lu]\n"),sHead,lEdges        ,sEdges.GetSize()  ) ;
                                             SE_MSG(SM_ERR,sBuff) ;
                                             eStat = SM_ERR;
                                           }
  if(lVertices      != sVertices.GetSize()){ smos_sprintf(sBuff,_T("%.512sVertex Count        [exp:%lu, act:%lu]\n"),sHead,lVertices     ,sVertices.GetSize());
                                             SE_MSG(SM_ERR,sBuff) ;
                                             eStat = SM_ERR;
                                           }
  if(lWireEdges     != lWires)             { smos_sprintf(sBuff,_T("%.512sWire Count          [exp:%lu, act:%lu]\n"),sHead,lWireEdges    ,lWires            ) ;
                                             SE_MSG(SM_ERR,sBuff) ;
                                             eStat = SM_ERR;
                                           }
  if(lLaminaEdges   != lLaminas)           { smos_sprintf(sBuff,_T("%.512sLamina Edge Count   [exp:%lu, act:%lu]\n"),sHead,lLaminaEdges  ,lLaminas          ) ;
                                             SE_MSG(SM_ERR,sBuff) ;
                                             eStat = SM_ERR;
                                           }
  if(lManifoldEdges != lManifold)          { smos_sprintf(sBuff,_T("%.512sManifold Edge Count [exp:%lu, act:%lu]\n"),sHead,lManifoldEdges,lManifold         ) ;
                                             SE_MSG(SM_ERR,sBuff) ;
                                             eStat = SM_ERR;
                                           }
  if(lRegions       != sRegions.GetSize()) { smos_sprintf(sBuff,_T("%.512sRegion Count        [exp:%lu, act:%lu]\n"),sHead,lRegions      ,sRegions.GetSize()) ;
                                             SE_MSG(SM_ERR,sBuff) ;
                                             eStat = SM_ERR;
                                           }
  if(lShells        != lNumShells)         { smos_sprintf(sBuff,_T("%.512sShell Count         [exp:%lu, act:%lu]\n"),sHead,lShells       ,lNumShells        ) ;
                                             SE_MSG(SM_ERR,sBuff) ;
                                             eStat = SM_ERR;
                                           }
  SER( eStat) ;

#ifdef SM_DEBUG_CODE
SmBoolean bDebug = FALSE ;
  if(bDebug)
    {
      ULONG di ;
      SM_DUMP_AND_ASSERT_VALID(this) ;

      smgfx_Erase() ;
      smgfx_SetLook(1,2, 0,0,1) ; this->Draw(TRUE) ; sm_GraphicsLoop() ;
      smgfx_SetLook(1,2, 0,0,1) ; this->DrawUV() ; sm_GraphicsLoop() ;
      smgfx_SetLook(2,4) ; 
      for(di=0;di<sEdges.GetSize();di++) 
      {
        smgfx_ChangeColor( di != 0) ; if(sEdges[di]) { sEdges[di]->Draw(); sm_GraphicsLoop(); }
      }
      smgfx_SetLook(1,2) ; 
      for(di=0;di<sFaces.GetSize();di++) 
      {
        smgfx_ChangeColor( di != 0) ; if(sFaces[di]) { sFaces[di]->DrawUV(); sm_GraphicsLoop(); }
      }
      sm_GraphicsLoop() ;
    }
#endif // SM_DEBUG_CODE

  // all done
  return SM_SUCCESS ;

} // end SmBrep::ValidateCounts

/*******************************************************************//**
PURPOSE: Compare entity counts between 2 Breps.

NOTES: compares numbers of vertices,
                                    edges,
                                    wire edges,
                                    lamina edges,
                                    manifold edges,
                                    faces,
                                    shells,
                                    Regions.

RETURNS --- TRUE  = all counts are the same
            FALSE = some counts are different.
***********************************************************************/
SmBoolean SmBrep::CompareCounts(const SmBrep *pBrep2) const
{
  // locals
  ULONG ii ;
  const SmBrep *pBrep1 = this ;

  SmTArray<SmFace*>   sFaces1,     sFaces2;
  SmTArray<SmEdge*>   sEdges1,     sEdges2;
  SmTArray<SmVertex*> sVertices1,  sVertices2;
  pBrep1->GetFaces(sFaces1);       pBrep2->GetFaces(sFaces2);
  pBrep1->GetEdges(sEdges1);       pBrep2->GetEdges(sEdges2);
  pBrep1->GetVertices(sVertices1); pBrep2->GetVertices(sVertices2);

  ULONG lWires1    = 0, lWires2    = 0;
  ULONG lLaminas1  = 0, lLaminas2  = 0;
  ULONG lManifold1 = 0, lManifold2 = 0;
  for (ii=0; ii<sEdges1.GetSize(); ii++)
    {
      SmEdge *pE = sEdges1[ii];
      if (pE->IsWire())     lWires1++;
      if (pE->IsLamina())   lLaminas1++;
      if (pE->IsManifold()) lManifold1++;
    }

  for (ii=0; ii<sEdges2.GetSize(); ii++)
    {
      SmEdge *pE = sEdges2[ii];
      if (pE->IsWire())     lWires2++;
      if (pE->IsLamina())   lLaminas2++;
      if (pE->IsManifold()) lManifold2++;
    }

  SmTArray<SmRegion*> sRegions1, sRegions2;
  SmTArray<SmShell*>  sShells1,  sShells2;
  GetRegions(sRegions1); GetRegions(sRegions2);
  ULONG lNumShells1=0, lNumShells2=0;

  for ( ii=0; ii<sRegions1.GetSize(); ii++)
    {
      SmRegion *pR = sRegions1[ii];
      pR->GetShells(sShells1);
      lNumShells1 += sShells1.GetSize();
    }

  for ( ii=0; ii<sRegions2.GetSize(); ii++)
    {
      SmRegion *pR = sRegions2[ii];
      pR->GetShells(sShells2);
      lNumShells2 += sShells2.GetSize();
    }

  SmBoolean bRtn = TRUE ;
  if (sFaces1.GetSize()    != sFaces2.GetSize())    bRtn = FALSE ;
  if (sEdges1.GetSize()    != sEdges2.GetSize())    bRtn = FALSE ;
  if (sVertices1.GetSize() != sVertices2.GetSize()) bRtn = FALSE ;
  if (lWires1              != lWires2)              bRtn = FALSE ;
  if (lLaminas1            != lLaminas2)            bRtn = FALSE ;
  if (lManifold1           != lManifold2)           bRtn = FALSE ;
  if (sRegions1.GetSize()  != sRegions2.GetSize())  bRtn = FALSE ;
  if (lNumShells1          != lNumShells2)          bRtn = FALSE ;

  // all done
  return(bRtn) ;

} // end SmBrep::CompareCounts


