/*******************************************************************//**
PURPOSE: Test this Brep with consistency checks

NOTES:
  1. This routine is intended to document the rules of what is
     and is not a legal SMLib SmBrep.

  2. This routine will never make any changes to the Brep except
     to refresh cached data.

RETURNS ---  TRUE  = OK
             FALSE = Problem
***********************************************************************/
SmBoolean SmBrep::AssertValid
 (SmAssertArray    * pAList,        // i/o: Accumulating list of failed Asserts, NULL to ignore, default:[NULL]
  SmAssertTestLevel  eTestLevel,    // in : SM_LEVEL_0=fewest tests, SM_LEVEL_1, SM_LEVEL_2=all tests,
                                    //      SM_LEVEL_GIVEN = run tests in order requested in pTestRequests
                                    //      default:[SM_LEVEL_0]
  SmAssertWalking    eWalkTree,     // in : SM_WALK = run AssertValid on any topology graph descendants, SM_NO_WALK=don't, default:[SM_WALK]
  SmTArray<ULONG>  * pTestRequests) // in : when eTestLevel == SM_LEVEL_GIVEN, run these tests in this order, default:[NULL]
 const
{
#ifdef SM_DEBUG_CODE
SmBoolean bDebugMe = FALSE ;
  if(bDebugMe)
    {
      this->Dump(_T("From SmBrep::AssertValid\n")) ;
    }
#endif // SM_DEBUG_CODE

  // Init rtn value, and invoke higher-level checks.
  SmBoolean bRtn = TRUE ;

  // call the base class AssertValid
  bRtn &= (  (eTestLevel != SM_LEVEL_GIVEN)
           ? SmSAGObject::AssertValid(pAList, eTestLevel, SM_NO_WALK, pTestRequests)
           : TRUE ) ;

  // Old style checks: ValidatePointers() and ValidateAndUpdateTolerances().
  // (Note, no 'updating' is done.)

  // locals for old style checking
  SmBoolean bTolerancesViolatedOrUpdated = false;
  double dMaxEdgeFaceTrimCurveGap ;
  double dMaxVertexEdgeGap ;
  double dMaxVertexFaceGap ;
  double dMaxEdgeFaceGap ;
  double dMaxVertexFaceTrimCurveGap ;
  SmStatus eStat = ValidatePointers(pAList, SM_LEVEL_0, NULL, eWalkTree) ;
  if(eStat != SM_SUCCESS )
    { 
      return FALSE; 
    }

  // old style ValidateAndUpdateTolerances check
  SmEdgeuse   *pMaxEdgeFaceTrimCurveObj ;
  SmVertexuse *pMaxVertexEdgeObj ;
  SmVertexuse *pMaxVertexFaceObj ;
  SmEdgeuse   *pMaxEdgeFaceObj ;
  SmEdgeuse   *pMaxEdgeuseVertexObj ;

  eStat = ((SmBrep *)this)->ValidateAndUpdateTolerances    // increments unlocked mark value
              (TRUE,  //  TRUE = just check, false = also fix, tolerances
               bTolerancesViolatedOrUpdated,
               dMaxEdgeFaceTrimCurveGap,
               dMaxVertexEdgeGap,
               dMaxVertexFaceGap,
               pAList,
               eTestLevel,
               pTestRequests,

              &pMaxEdgeFaceTrimCurveObj,
              &pMaxVertexEdgeObj,
              &pMaxVertexFaceObj,
              &pMaxEdgeFaceObj,
              &pMaxEdgeuseVertexObj,

              &dMaxEdgeFaceGap,
              &dMaxVertexFaceTrimCurveGap) ;

  // Warn if any member BrepObjects need their tolerances increased.
  if(bTolerancesViolatedOrUpdated)
    {
      TCHAR sBuff[SM_TBLOCK_SIZE];
      WARN((_T("SmBrep::ValidateAndUpdateTolerances WARNING - Some member BrepObject tolerances need to be increased."))) ;
      smos_sprintf(sBuff,_T("%s"),_T("           note: Problem only found - no changes made to fix anything." ));    smos_WriteBuffer(sBuff) ;

#ifdef SM_USE_NEWTOL
      SM_NEWTOL_LINE smos_sprintf(sBuff,_T("\n            Max Edge/FaceTrimCurve Gap   = %16.16lf, BrepZoneTol3d:[%16.16lf], ModelSizeEst:[%16.16lf], LargeSmallSizeRatio:[%16.16lf]"), dMaxEdgeFaceTrimCurveGap, GetThisZoneTol3d(), GetThisModelSizeEstimate(), GetThisLargeSmallSizeRatio()) ; smos_WriteBuffer(sBuff) ;
#else  // SM_USE_OLDTOL
      SM_OLDTOL_LINE smos_sprintf(sBuff,_T("\n            Max Edge/FaceTrimCurve Gap   = %16.16lf, BrepZoneTol3d:[%16.16lf]"),dMaxEdgeFaceTrimCurveGap,(double)m_sThisZoneTol3d) ; smos_WriteBuffer(sBuff) ;
#endif // SM_USE_OLDTOL

      smos_sprintf(sBuff,_T("\n            Max Vertex/Edge Gap          = %16.16lf"),    dMaxVertexEdgeGap) ;        smos_WriteBuffer(sBuff) ;
      smos_sprintf(sBuff,_T("\n            Max Vertex/Face Gap          = %16.16lf"),    dMaxVertexFaceGap) ;        smos_WriteBuffer(sBuff) ;
      smos_sprintf(sBuff,_T("\n            Max Edge/Face Gap            = %16.16lf"),    dMaxEdgeFaceGap) ;          smos_WriteBuffer(sBuff) ;
      smos_sprintf(sBuff,_T("\n            Max Vertex/FaceTrimCurve Gap = %16.16lf"),    dMaxVertexFaceTrimCurveGap) ; smos_WriteBuffer(sBuff) ;

#ifdef SM_DEBUG_CODE
      // draw
      if(bDebugMe)
      {
        SmSurface *pEUSurface = (pMaxEdgeFaceTrimCurveObj && pMaxEdgeFaceTrimCurveObj->GetFace()) ? pMaxEdgeFaceTrimCurveObj->GetFace()->GetSurface() : NULL;
        SmCurve   *pEUCurveUV = pMaxEdgeFaceTrimCurveObj ? pMaxEdgeFaceTrimCurveObj->GetUVTrimCurvePointer() : NULL;
        SmCurve   *pEUCurve3d = (pMaxEdgeFaceTrimCurveObj && pMaxEdgeFaceTrimCurveObj->GetEdge()) ? pMaxEdgeFaceTrimCurveObj->GetEdge()->GetCurve() : NULL;
        SmZoneTol3d sZoneTol3d = GetTolerance();

        smgfx_Erase();
        smgfx_SetLook( 1, 2, 0, 0, 1) ; this->Draw( TRUE) ; sm_GraphicsLoop();
        smgfx_SetLook( 2, 3, 1, 0, 1) ; if(dMaxEdgeFaceTrimCurveGap > sZoneTol3d && pMaxEdgeFaceTrimCurveObj)
                                          { pMaxEdgeFaceTrimCurveObj->Draw(); sm_GraphicsLoop();}
        smgfx_SetLook( 2, 3, 1, 0, 1) ; if(dMaxEdgeFaceTrimCurveGap > sZoneTol3d && pEUSurface && pEUCurveUV && pEUCurve3d)
                                          { pEUSurface->DrawInspectUVTrimCurve( *pEUCurveUV, *pEUCurve3d) ; sm_GraphicsLoop();}
        smgfx_SetLook( 5, 6, 1, 0, 0) ; if(dMaxVertexEdgeGap > sZoneTol3d && pMaxVertexEdgeObj && pMaxVertexEdgeObj->GetVertex())
                                           {pMaxVertexEdgeObj->GetVertex()->Draw(); sm_GraphicsLoop();}
        smgfx_SetLook( 7, 8, 0, 0, 0) ; if(dMaxVertexFaceGap > sZoneTol3d && pMaxVertexFaceObj && pMaxVertexFaceObj->GetVertex())
                                        { pMaxVertexFaceObj->GetVertex()->Draw(); sm_GraphicsLoop();}
          sm_GraphicsLoop() ;
        }
#endif // SM_DEBUG_CODE

    }  // end bTolerancesViolatedOrUpdated check

  // new style - remember failures and keep checking
  bRtn &= ( eStat == SM_SUCCESS ) ;
  //      if(eStat != SM_SUCCESS )
  //        {
  //          return FALSE; 
  //        }

  // Walk the Topology graph checks.
  ULONG ii, jj ;
  SmTArray<SmRegion *> sRegions ;
  SmTArray<SmShell  *> sShells, sRegionShells ;
  SmTArray<SmFace   *> sFaces ;
// Remove Composites
// SmTArray<SmCFace   *> scFaces ;
  SmTArray<SmLoop   *> sLoops ;
  SmTArray<SmEdge   *> sEdges ;
// Remove Composites
// SmTArray<SmCEdge  *> sCEdges ;
  SmTArray<SmVertex *> sVertices ;

  GetRegions (sRegions) ;
  GetShells  (sShells) ;
  GetFaces   (sFaces) ;
// Remove Composites
// GetCFaces  (sCFaces) ;
  GetEdges   (sEdges) ;
// Remove Composites
// GetCEdges  (sCEdges) ;
  GetVertices(sVertices) ;

  ULONG lNumRegions = sRegions .GetSize();
  ULONG lNumFaces   = sFaces   .GetSize();
  ULONG lNumEdges   = sEdges   .GetSize();
  ULONG lNumVertices= sVertices.GetSize();

  const SmContext *pThisContext = this->GetContext();

  // SmBrep and the objects it attaches to need to share common contexts
  if(m_pInfiniteRegion)  { bRtn &= SM_ASSERT_BOOLEAN_REPORT(0, SM_LEVEL_0, (m_pInfiniteRegion->GetContext()  == pThisContext), _T("") ) ;   }

  if(m_pFaceListHead)    { bRtn &= SM_ASSERT_BOOLEAN_REPORT(1, SM_LEVEL_0, (m_pFaceListHead->GetContext()    == pThisContext), _T("") ) ; }
      // m_pFaceListHead->AssertValid() ;   // don't make test because these lists are not used in the typical fashion

  if(m_pEdgeListHead)    { bRtn &= SM_ASSERT_BOOLEAN_REPORT(2, SM_LEVEL_0, (m_pEdgeListHead->GetContext()    == pThisContext), _T("") ) ; }
      // m_pEdgeListHead->AssertValid() ;   // don't make test because these lists are not used in the typical fashion

// Remove Composites
//   if(m_pCFaceListHead)   { bRtn &= SM_ASSERT_BOOLEAN_REPORT(3, SM_LEVEL_0, (m_pCFaceListHead->GetContext()   == pThisContext), _T("") ) ; }
//      // m_pCFaceListHead->AssertValid() ;  // don't make test because these lists are not used in the typical fashion

// Remove Composites
//  if(m_pCEdgeListHead)   { bRtn &= SM_ASSERT_BOOLEAN_REPORT(4, SM_LEVEL_0, (m_pCEdgeListHead->GetContext()   == pThisContext), _T("") ) ; }
//      // m_pCEdgeListHead->AssertValid() ;  // don't make test because these lists are not used in the typical fashion

  if(m_pVertexListHead)  { bRtn &= SM_ASSERT_BOOLEAN_REPORT(5, SM_LEVEL_0, (m_pVertexListHead->GetContext()  == pThisContext), _T("") ) ; }
      // m_pVertexListHead->AssertValid() ; // don't make test because these lists are not used in the typical fashion

  if(m_pDeletedSurfaces) { bRtn &= SM_ASSERT_BOOLEAN_REPORT(6, SM_LEVEL_0, (m_pDeletedSurfaces->GetContext() == pThisContext), _T("") ) ; }
      // m_pDeletedSurfaces->AssertValid() ;// don't make test because these lists are not used in the typical fashion

  // Regions must be separated by closed shells, which must be Faceuse shells.
  // So if there's more than one region, we must have faces.
  if(lNumRegions > 1 ) { bRtn &= SM_ASSERT_BOOLEAN_REPORT(7, SM_LEVEL_0, (lNumFaces >= 1), _T("") ) ; }

  // Check that the infinite region is actually the correct one.
  SmRegion *pInfiniteRegion = NULL;
  bRtn &= ( SM_SUCCESS == FindInfiniteRegion( pInfiniteRegion ));
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(8, SM_LEVEL_0, (pInfiniteRegion == m_pInfiniteRegion), _T("") ) ;

  // The infinite region must be first in the region list.
  pInfiniteRegion = GetInfiniteRegion() ;
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(9, SM_LEVEL_0, (pInfiniteRegion == sRegions[0]), _T("") ) ;

  // for Non-empty Breps
  if(   lNumFaces > 0
     || lNumEdges > 0
     || lNumVertices > 0)
    {
      // Check Region/Shell containment for every region.
      for( ii=0; ii<lNumRegions; ii++)
        {
          SmRegion *pRegion = sRegions[ii] ;
          pRegion->GetShells(sRegionShells) ;
          ULONG lNumRegionShells = sRegionShells.GetSize();

          // Every region (except the infinite region) should have at least one shell
          bRtn &= SM_ASSERT_BOOLEAN_REPORT(16, SM_LEVEL_0, (lNumRegionShells >= 1 || lNumRegions <= 1), _T("") ) ;
          if(lNumRegionShells < 1 && lNumRegions > 1)
            {
              SE_MSG( SM_ERR, _T("SmBrep::AssertValid() : Found Region with no Shells" ));
              continue ;
            }

          // The infinite region has no outer shell.
          // All other regions have one outer shell, and it is first in the list.
          SmShell *pOuterShell = ii==0 ? NULL : sRegionShells[0] ;

          // All regions other than the infinite region
          // must be surrounded by Faces, so its outer shell
          // must be a Faceuse shell.
          if(pOuterShell != NULL ) // Not the infinite region.
            {
              // outer shell must be a faceuse type
              bRtn &= SM_ASSERT_BOOLEAN_REPORT(10, SM_LEVEL_0, (pOuterShell->IsFaceuseShell()), _T("") ) ;

              // outer shell must be closed
              bRtn &= SM_ASSERT_BOOLEAN_REPORT(11, SM_LEVEL_0, (pOuterShell->IsClosed()), _T("") ) ;

#ifdef SM_DEBUG_CODE
              // draw
              if(bDebugMe)
                {
                  smgfx_Erase() ;
                  smgfx_SetLook(1,2, 0,0,1) ; this->Draw(TRUE) ; sm_GraphicsLoop() ;
                  smgfx_SetLook( 1, 2, 0, 1, 1) ; if(pOuterShell) { pOuterShell->Draw(); sm_GraphicsLoop(); }
                  sm_GraphicsLoop() ;
                }
#endif // SM_DEBUG_CODE

              //      // At least for now, make sure the caller doesn't miss it.
              //      if(!bThisRtn )
              //      {
              //          SE( SM_ERR) ;
              //          return FALSE;
              //      }
            }

          // for every inner shell - remember the infinite region has any number of inner shells
          for(jj= (ii==0)?0:1; jj<lNumRegionShells; jj++ )
            {
              SmShell *pInnerShell = sRegionShells[jj] ;

#ifdef SM_DEBUG_CODE
              // draw
              if(bDebugMe)
                {
                  smgfx_Erase() ;
                  smgfx_SetLook(1,2, 0,0,1) ; this->Draw(TRUE) ; sm_GraphicsLoop() ;
                  smgfx_SetLook( 1, 2, 0, 1, 1) ; if(pInnerShell) { pInnerShell->Draw(); sm_GraphicsLoop(); }
                  sm_GraphicsLoop() ;
                }
#endif // SM_DEBUG_CODE

              // use ray casting to make sure that nonInfiniteRegion inner shells are contained by outer shells
              bRtn &= SM_ASSERT_BOOLEAN_REPORT(12, SM_LEVEL_0, (pOuterShell == NULL || pInnerShell->IsInnerShellOf(pOuterShell) == TRUE), _T("") ) ;

            } // end iter every inner region
        } // end iter every region
    } // end nonEmpty Brep check

  // Another check:
  // If more than one region, then the infinite region must contain
  // at least one shell that's a closed Faceuse shell.
  SmTArray<SmFaceuse*> sFUs;

  if(lNumRegions > 1 )
    {
      SmBoolean bHasClosedShell = FALSE;
      SmRegion *pR = sRegions[0]; // infinite region
      pR->GetShells(sRegionShells);
      ULONG lNumShells = sRegionShells.GetSize();
      for ( ii = 0; ii < lNumShells; ii++ )
        {
          SmShell *pSh = sRegionShells[ii];
          if(! pSh->IsFaceuseShell() )
            { continue; }

          // Check shell closure.
          if(pSh->IsClosed() )
            {
              bHasClosedShell = TRUE;
              break;
            }
        }

      // When Brep has multiple regions, Infinite region must have at least 1 closed innerShell
      bRtn &= SM_ASSERT_BOOLEAN_REPORT(17, SM_LEVEL_0, (bHasClosedShell == TRUE), _T("") ) ;

      // new behavior: continue checking even after seeing a failure
      //      if(! bHasClosedShell )
      //        {
      //            SE( SM_ERR) ;
      //            return FALSE;  // Make sure the caller doesn't miss it.
      //        }
    } // end inf-reg-has-a-closed-FU-loop test


  // All Regions must be connected to each other, across Faceuses.
  // Check this Brep's list of Regions
  // against a list collected by a TopologyTraverser crawl.
  SmTArray< SmRegion* > sConnectedRegions;

  SmTopologyTraverser sTT;
  sTT.CollectRegions( m_pInfiniteRegion, sConnectedRegions) ;

  // The topology traverser doesn't put the given region in the list.
  sConnectedRegions.Add( m_pInfiniteRegion) ;

  // The two arrays should have all the same elements.
  // First check their sizes, then check common elements.

  // The number of regions found by a topology traversal should be the same as the Brep Region Count
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(18, SM_LEVEL_0, (sConnectedRegions.GetSize() == lNumRegions), _T("") ) ;

  // new behavior: continue checking even after seeing a failure
  //      if(sConnectedRegions.GetSize() != lNumRegions )
  //        {
  //            SE( SM_ERR) ;
  //            return FALSE;  // Make sure the caller doesn't miss it.
  //        }

  // Regions found by topology traversal should be the same as the Brep's region list
  SmTArray< SmRegion* > sCommonElements;
  sRegions.FindCommonElements( sConnectedRegions, sCommonElements);
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(19, SM_LEVEL_0, (sCommonElements.GetSize() == lNumRegions), _T("") ) ;

  // new behavior: continue checking even after seeing a failure
  //      if(sCommonElements.GetSize() != lNumRegions )
  //        {
  //            SE( SM_ERR) ;
  //            return FALSE;  // Make sure the caller doesn't miss it.
  //        }

  // See about running coincident-topology checks.
  bRtn &= this->ContainsCoincidentTopology(-1,NULL,NULL,pAList) ;
  // bRtn &= SM_ASSERT_BOOLEAN_REPORT(15, SM_LEVEL_2, (this->ContainsCoincidentTopology(-1,NULL,NULL,pAList)==FALSE), _T("") ) ;

  // Shell context checks.
  for(ii=0;ii<sShells.GetSize();ii++)
    {
       SmShell *pShell = sShells[ii] ;
       bRtn &= SM_ASSERT_BOOLEAN_REPORT(13, SM_LEVEL_0, (pShell->GetContext() == pThisContext), _T("") ) ;
    } // end iter every shell

  // Face context checks.
  for(ii=0;ii<sFaces.GetSize();ii++)
    {
       SmFace *pFace = sFaces[ii] ;
       bRtn &= SM_ASSERT_BOOLEAN_REPORT(14, SM_LEVEL_0, (pFace->GetContext() == pThisContext), _T("") ) ;
    } // end iter every shell

  // warn when Shell Count == Face Count in a multi-face NonManifold model. Suggest running Stitch()
  // this is a warning, so don't change the bRtn value
  ULONG lFaceuseShellCnt = 0 ;
  for(ii=0;ii<sShells.GetSize();ii++) { if(sShells[ii]->IsFaceuseShell()) lFaceuseShellCnt++ ; }
  SM_ASSERT_BOOLEAN_REPORT(21, SM_LEVEL_0, (    IsManifoldSolid()
                                            || (sFaces.GetSize() != lFaceuseShellCnt)
                                            || (sFaces.GetSize() <= 1)), 
                                           _T("") ) ;


  // Breps with only lamina edges must have as many shells as faces
  // No: can have sheet faces connected only at Vertices.  [B467 B468]
//  ULONG lNumLaminaEdges = 0 ;
//  for(ii=0;ii<lNumEdges;ii++) { if(sEdges[ii]->IsLamina()) { lNumLaminaEdges++ ; } }
//  bRtn &= SM_ASSERT_BOOLEAN_REPORT(22, SM_LEVEL_0, (   (lNumLaminaEdges != sEdges.GetSize())
//                                                    || (lFaceuseShellCnt == sFaces.GetSize())), 
//                                                   _T("") ) ;

  /* 30 */ // Brep's stored ZoneTol must equal the SmTol::Consistent Tolerance Model value
#ifdef SM_USE_OLDTOL
#ifdef SM_NMTLIB_7166
  bRtn &= SM_ASSERT_BOOLEAN_REPORT(30, SM_LEVEL_2, sm_AssertTestBrep23(this) == TRUE, _T("")) ;
#endif // SM_NMTLIB_7166
#endif // SM_USE_OLDTOL

  // when asked - AssertValid for a topology graph traversal
  if(eWalkTree == SM_WALK)
    {
      bRtn &= SmBrep::AssertSubTopology( (SmTopology &)*this, pAList, eTestLevel) ;
      // bRtn &= SM_ASSERT_BOOLEAN_REPORT(20, SM_LEVEL_0, (SmBrep::AssertSubTopology( (SmTopology &)*this, pAList, eTestLevel)), _T("")) ;

    } // end asked to walk the tree check

  // all done
  // SM_ASSERT_MSG(bRtn, _T("SmBrep::AssertValid: Errors Found")) ;
  return(bRtn) ;

} // end SmBrep::AssertValid

