  // Vertices
  smos_sprintf(sBuff,_T("\n\nBrep = 0x%p has %ld %s "), this, sVertices.GetSize(), sVertices.GetSize() == 1 ? _T("Vertex") : _T("Vertices")) ; smos_WriteBuffer(sBuff, sBuffForFile);
