  smos_sprintf(sBuff,_T("\n\nBrep = 0x%p has %ld Curve%s "), this, sCurves.GetSize(), sCurves.GetSize() == 1 ? _T("") : _T("s")) ; smos_WriteBuffer(sBuff, sBuffForFile);
