/*******************************************************************//**
PURPOSE: Delete any stale TrimSrfCaches.

NOTES:
   Stale caches are not always deleted, they are just marked: m_bFaceWasModified.
   When getting/creating them, if the Brep m_bEditingEnabled flag is True,
   then the old cache will be used, even if it's stale.  That requires that
   the caller of certain routines would have to temporarily set the Brep's
   EditingEnabled flag to False, which is not a good way to do things.
   It would be a good idea to call this method at the end of major operations,
   such as SmMerge::ManifoldBoolean().  [B352]
***********************************************************************/
SmStatus SmBrep::DeleteStaleCaches()
{
  // locals
  ULONG ii ;
  SmSurface      * pSurf  = NULL;
  SmSurfaceCache * pCache = NULL;
  SmFace         * pF     = NULL;

  // get the first Brep Face
  SmFace *pStartFace = SM_CAST_PTR( SmFace, this->m_pFaceListHead->GetList()) ;

  // no work - no faces
  if(pStartFace == NULL )
    { return SM_SUCCESS; }

  // For every Face - delete stale Surface caches
  for(pF=pStartFace, ii=0;
      (pF!=pStartFace || ii==0) && pF!=NULL;
      pF=SM_CAST_PTR( SmFace, pF->GetNext()), ii++)
    {
      pSurf  = pF->GetSurface();
      pCache = (SmSurfaceCache *)SmCacheMgr::GetObjectCache( SM_OC_TRIMSRF, pSurf) ;

      // skip faces without surfaces or without caches
      if(   pSurf==NULL
         || pCache == NULL)
        { continue; }

      // if the cache is marked as modified - delete the cache
      if(pCache->m_bFaceWasModified)
        {
          SmCacheMgr::DeleteObjectsCache( SM_OC_TRIMSRF, pSurf) ;
        }
    } // end iter every pFace

  // all done
  return SM_SUCCESS;

} // end SmBrep::DeleteStaleCaches

