/*******************************************************************//**
PURPOSE:  Something we may add someday.

NOTES:
***********************************************************************/
void SmBrep::RemoveHoles
  ( )
{
  this->Transform3D();
  SmBrep* originalBrep = this->wrap.Get()->fBrep;

  // first lets mark all the loops
  // if any loops are already flagged then leave the remaining unflagged
  // if none are already flagged then mark all of them
  SmTArray <SmFace*> faces;
  originalBrep->GetFaces( faces) ;
  long nFaces = faces.GetSize();

  ULONG flag = 0;
  bool loopsAreFlagged = FALSE;

  SmTArray <SmLoop*> loops;
  for( long i = 0; i < nFaces;i++ ) {
    faces[i]->GetLoops(loops);
    long nLoops = loops.GetSize();
    for (long ii = 0; ii < nLoops; ii++ ) {
      SmLoop* loop = loops[ii];
      flag = loop->GetAllFlags();
      if( flag == 9 ) {
        if( IsCircularLoop( loop, faces[i]->GetSurface() ) ) {
          loopsAreFlagged = TRUE;
        }
        else {
          loop->ClearAllFlags();
        }
      }
    }
  }

  if( !loopsAreFlagged ) {
    for( i = 0; i < nFaces;i++ ) {
      SmFace* face = faces[i];
      face->GetLoops(loops);
      long nLoops = loops.GetSize();
      for (long ii = 0; ii < nLoops; ii++ ) {
        SmLoop* loop = loops[ii];
        if( IsCircularLoop( loop, face->GetSurface() ) ) {
          loop->SetFlag( 9) ;
        }
      }
    }
  }

  // now remove the loops that are flagged. We do this by plugging the hole
  // with a new face, indentifying the faces on the other side of the loop,
  // copy those to a new brep, and now remove them from this brep.
  bool done = FALSE;
  while( !done ) {
    done = TRUE;

    faces.ReSet();
    originalBrep->GetFaces( faces) ;
    long nFaces = faces.GetSize();

    for( i = 0; i < nFaces;i++ ) {
      SmFace* face = faces[i];
          SmFaceuse *pFU = face->GetUpwardFaceuse();
          SmTArray<SmLoopuse*> sLoopuses;
      pFU->GetLoopuses(sLoopuses);
      long nLoops = sLoopuses.GetSize();
      for (long ii = 0; ii < nLoops; ii++ ) {
        SmLoop *loop = sLoopuses[ii]->GetLoop();

        // make sure loop is an inner loop or trim curve
        if( !loop->IsOuterLoop() && loop->GetAllFlags() == 9 ) {
          loop->ClearAllFlags();

                  SmTArray<SmFace*> sFacesToRemove;
          SmTArray<SmFace*> sTmpFaces;

          SmTArray<SmEdgeuse*> sEdgeuses;
          sLoopuses[ii]->GetEdgeuses(sEdgeuses);

          int nEdgeUses = sEdgeuses.GetSize();
          for( long k = 0; k < nEdgeUses; k++ ) {
            SmEdge *pE = sEdgeuses[k]->GetEdge();
            pE->GetFaces(sTmpFaces);

            int nTmpFaces = sTmpFaces.GetSize();
            for (long kk = 0; kk<nTmpFaces; kk++ ) {
              SmFace* faceToRemove = sTmpFaces[kk];
              if( faceToRemove != face ) {
                sFacesToRemove.AddUnique( faceToRemove) ;
              }
            }
          }

          // keep track of how many shells in the original brep
          SmTArray <SmShell*> originalShells;
          originalBrep->GetShells( originalShells) ;
          int nOriginalShells = originalShells.GetSize();

          // copy the faces to another brep before removing
          SmBrep *newBrep = new ( *smContext ) SmBrep();
          newBrep->SetTolerance(originalBrep->GetTolerance());
          originalBrep->CopyFaces( sFacesToRemove, newBrep) ;

          // plug up face where hole was
          SmTArray<ULONG> sLoops;
          sLoops.Add(sEdgeuses.GetSize());
                  SmTArray<SmVertex*> sLoopVertices;
                  SmSurface *pSurface = face->GetSurface();
          SmExtent2d sUVDomain = pSurface->GetNaturalUVDomain();
          SmRegion *pNewReg;
          SmShell *pNewShell;
          SmFace *pNewFace;
          originalBrep->MakeFace( originalBrep->GetInfiniteRegion(),sLoops,sEdgeuses,
            sLoopVertices,pSurface,sUVDomain,SM_OT_OPPOSITE,pNewReg,pNewShell,pNewFace);

          // remove faces from this brep
          originalBrep->m_bEditingEnabled = TRUE;
          originalBrep->RemoveFaces( sFacesToRemove) ; // increments unlocked mark value
          originalBrep->m_bEditingEnabled = FALSE;

          // now hole is plugged and cylindrical face is removed
          // lets try and find the other faces that might be dangling
          sFacesToRemove.ReSet();

          SmTArray <SmShell*> newShells;
          originalBrep->GetShells( newShells) ;
          int nNewShells = newShells.GetSize();

          // if a new shell was created by removing the cylindrical
          // face, then we must remove the dangling faces
          if( nNewShells > nOriginalShells ) {

            // new shell is always the first shell
            // I need to confirm this with lots of tests
            SmShell* shell = newShells[0];
            SmTArray <SmFaceuse*> tmpFaceuses;
            shell->GetFaceuses( tmpFaceuses) ;
            int nFaceuses = tmpFaceuses.GetSize();
            for( int f = 0; f < nFaceuses; f++ ) {
              SmFaceuse* faceuse = tmpFaceuses[f];
              sFacesToRemove.AddUnique( faceuse->GetFace()) ;
            }

            originalBrep->CopyFaces( sFacesToRemove, newBrep) ;
            originalBrep->m_bEditingEnabled = TRUE;
            originalBrep->RemoveFaces( sFacesToRemove) ;  // increments unlocked mark value
            originalBrep->m_bEditingEnabled = FALSE;
          }

          // place all copied faces into new csmbrep
          // and add to database
          CSmBrep newCsmBrep;
          newCsmBrep.SetBrep( newBrep) ;
          CENTITYCAST(newCsmBrep).SetPick(FALSE);
          CENTITYCAST(newCsmBrep).SetVis(FALSE);
          cgdb->AddEntAll(&newCsmBrep, ENT_NODEFAULT);

          // get out of loop
          i = nFaces;
          done = FALSE;
          break;
        }
      }
    }
  } // end while


} // end SmBrep::RemoveHoles

#endif // 0

/*******************************************************************//**
PURPOSE:

RETURNS --- This returns the smallest edge as measured by its min-max box
            diagonal. It also returns the pointer to the smallest edge.
***********************************************************************/
void SmBrep::GetMinEdgeBBoxSize
(
  double   & rdSize, 
  SmEdge * & rpEdge
) const
{
    SmExtent3d pBox;
    double dSize2;
    SmEdge *pE;
    SmPoint3d dDiff;
    SmTArray<SmEdge *> sEdges;
    GetEdges(sEdges);
    if (sEdges.GetSize() < 1)
    { // the no-edge brep returns standard default 0.001
        rdSize = 0.001;
        return;
    }
    rdSize = 1234567.0;
    for (ULONG ii = 0; ii< sEdges.GetSize(); ii++)
    {
        pE = sEdges[ii];
        // this is a slow process depending on tessellation
        pE->CalculateBoundingBox (&pBox, NULL, NULL);
        dDiff = pBox.GetSize();
        dSize2 = dDiff.LengthSquared();
        if(dSize2 < rdSize && dSize2 > SM_EFF_ZERO)
        {
            rdSize = dSize2;
            rpEdge = pE;
        }
    }
    rdSize = smos_Sqrt(rdSize);

    return;
} // SmBrep::GetMinEdgeBBoxSize

